  "{0} and {1} are spilling one another's Christian blood. Carry a Papal nuncio from one ruler's court to the other, and bring back both replies.": "{0}과 {1}은 서로 싸우며 기독교인의 피를 흘리고 있습니다. 교황 사절을 한 통치자의 궁정에서 다른 통치자의 궁정으로 모시고 가 양측의 답변을 받아 오십시오.",
