  "{0} at last. Here is the payment I promised.": "드디어 {0}에 도착했습니다. 약속한 사례금을 드립니다.",
  "{0} at last. I had nearly forgotten how a familiar harbor sounds.": "드디어 {0}에 도착했습니다. 익숙한 항구의 소리를 거의 잊을 뻔했습니다.",
  "{0} at last. I left home as a pilgrim and now return from the Hajj. Thank you.": "드디어 {0}에 돌아왔습니다. 순례자로 고향을 떠났다가 이제 하지를 마치고 돌아옵니다. 고맙습니다.",
  "{0} at last. I went looking for stories from the past and came back with enough to fill a tavern.": "드디어 {0}에 도착했군요. 옛이야기를 찾아 떠났다가 선술집을 가득 채울 만큼 많은 이야기를 가져왔습니다.",
  "{0} at last. My family will remember your kindness. Here are the {1} db I owe.": "드디어 {0}에 도착했군요. 가족에게 당신의 친절을 전하겠습니다. 빚진 더블룬 {1}닢을 받으세요.",
  "{0} at last. The treasury will settle our account.": "드디어 {0}에 도착했습니다. 국고에서 받을 돈을 정산해 줄 것입니다.",
  "{0} ATTACK DEFLECTED": "{0}의 공격을 막아냈습니다",
  "{0} authorizes you to take ships belonging to enemies of {1} as prizes.": "{0}은 {1}의 적선을 나포해 전리품으로 삼도록 허가합니다.",
