  "{0} BECOMES ROMAN EMPEROR": "{0}이 로마 황제가 되었습니다",
  "{0} Before we leave, I can show your crew a freshwater spring and where I found edible roots and shellfish.": "{0} 떠나기 전에 승무원들에게 담수 샘과 식용 뿌리와 조개류를 발견한 곳을 보여 드릴 수 있습니다.",
  "{0} Before we leave, I can show your crew a freshwater spring hidden above the beach.": "{0} 떠나기 전에 승무원들에게 해변 위에 숨겨진 담수 샘을 보여드릴 수 있습니다.",
  "{0} Before we leave, I can show your crew where I found edible roots and shellfish.": "{0} 떠나기 전에 승무원들에게 제가 식용 뿌리와 조개류를 발견한 곳을 알려드릴 수 있습니다.",
  "{0} believes {1} is within reach. I should find it, then return to {2}.": "{0}은 {1}이(가) 도달할 수 있는 거리에 있다고 믿습니다. 찾아서 {2}로 돌아가야 합니다.",
