  "{0} doubloons. Enough to delay my plans, not enough to settle your debt. You keep {1}; {2} remains due.": "더블룬 {0}닢. 내 계획을 미룰 수는 있어도 당신의 빚을 갚기엔 부족하군요. {1}은 남겨 두세요. 아직 {2}이 남았습니다.",
