  "{0} entrusts you with {1}. Carry me and the sealed cargo to {2}, then return with the receiving court's acknowledgment. Payment is {3} doubloons. Cargo: {4}.": "{0}이 귀하에게 {1}을 맡겼습니다. 저와 봉인된 화물을 {2}으로 데려간 다음, 수령 법원의 확인서를 가지고 돌아오세요. 결제 금액은 {3} 금화입니다. 화물: {4}.",
  "{0} envoy: {1}": "{0} 특사: {1}",
  "{0} escort": "{0} 호위",
  "{0} Every cask was already full.": "{0} 모든 통이 이미 가득 찼습니다.",
