  "{0} EXPEDITION OFFICE MOVED FROM {1} TO {2} AFTER THE PORT CHANGED HANDS": "항구의 지배권이 바뀌어 {0} 원정 사무소를 {1}에서 {2}로 옮겼습니다.",
