  "Cranes swing over the crowded wharf while guild clerks tally barrels, bales, and ships waiting on the tide.": "크레인이 붐비는 부두 위로 흔들리고 길드 직원은 조수를 기다리고 있는 통, 더미, 선박을 집계합니다.",
