  "Create a domestic matchlock industry in Japan.": "일본에 자국산 화승총 산업을 세우세요.",
  "Creation and destruction from one furnace. Mark the fresh flows separately from the cultivated slopes; the island's prosperity and danger share a source.": "한 화산이 창조와 파괴를 모두 일으킵니다. 새 용암류와 경작지를 따로 표시하세요. 섬의 번영과 위험은 같은 화산에서 비롯됩니다.",
