  "Current harpoon: {0}. A stronger line and truer shaft improve the odds of holding a surfaced whale. Purse {1} db.": "현재 작살: {0}. 튼튼한 작살줄과 곧은 자루는 수면 위로 떠오른 고래를 붙잡을 가능성을 높입니다. 비용: {1}더블룬.",
