  "Discovered {0}": "{0} 발견됨",
  "Disease and hunger have emptied the fort. Relations with Powhatan have worsened as the English demand food the drought has made scarce for everyone.": "질병과 굶주림이 요새를 텅 비게 만들었습니다. 가뭄으로 인해 식량이 부족해진 영국인들이 식량을 요구하면서 포와탄과의 관계는 더욱 악화되었습니다.",
