  "Distinct ship types sailed": "항해하는 다양한 선박 유형",
  "Diu kept its walls free of Portugal. Your estate was less fortunate with me.": "디우는 포르투갈을 성벽 밖에 막아 냈지만, 당신의 영지는 나를 막아 내지 못했지요.",
