  "Present the joint rebuilding plan": "공동 재건 계획 제시",
  "PRESS ANY KEY TO RETURN TO START MENU": "시작 메뉴로 돌아가려면 아무 키나 누르세요.",
  "Price tip: {0}": "가격 팁: {0}",
