  "Prince-Archbishop": "왕자 대주교",
  "Prince-Archbishop {0}": "대주교 왕자 {0}",
  "Prince-Archbishopric of Magdeburg": "마그데부르크 대주교후령",
  "Prince-Bishop": "프린스 비숍",
  "Prince-Bishop {0}": "프린스-비숍 {0}",
  "Prince-Bishopric of Liege": "리에주 주교후령",
  "Prince-Bishopric of Utrecht": "위트레흐트 대주교",
  "princes and envoys made peace. The treasury will pay the reward for": "왕자들과 사절들이 평화를 이루었습니다. 재무부가 보상금을 지급할 것입니다.",
  "Princes change in Targoviste. A sealed debt survives every throne.": "Targoviste에서 왕자가 변경됩니다. 봉인된 빚은 모든 왕좌에서 살아남습니다.",
