  "Relations are sour. The customs house will take {0}% from your trade.{1}": "관계가 신랄합니다. 세관에서는 거래 금액의 {0}%를 가져갑니다.{1}",
  "RELATIONS IMPROVE: {0} / {1}": "관계 개선: {0} / {1}",
