  "Reload {0}s / Damage x{1} / Range x{2}": "{0}초 / 피해량 x{1} / 범위 x{2} 다시 로드",
  "RELOAD {0}S DAMAGE x{1} RANGE x{2}": "재장전 {0}S 피해 x{1} 범위 x{2}",
  "Reload {0}s, damage x{1}, range x{2}": "{0}s 다시 로드, 손상 x{1}, 범위 x{2}",
  "Remain Roman Catholic": "로마 가톨릭에 남기",
  "Remarkable. Leave the penguin in my care and I shall pay you {payment} doubloons. I have fish, ink, and several questions he may decline to answer.": "놀랍습니다. 펭귄을 제게 맡기시면 제가 {지불} 더블룬을 지불하겠습니다. 나는 물고기, 잉크, 그리고 그가 대답을 거부할 수 있는 몇 가지 질문을 가지고 있습니다.",
  "Remember me when that bright sail rises over the horizon.": "저 밝은 돛이 지평선 위로 떠오를 때 나를 기억해주세요.",
  "remember who carried its cause across the sea.": "누가 바다 건너에서 그 대의를 수행했는지 기억하십시오.",
  "Renew the Sea Road": "바다길을 새롭게 하라",
  "Repaid the family debt in full and reclaimed the estate.": "가계 빚을 전액 갚고 재산을 되찾았습니다.",
  "Repairs {0} hull per day": "하루 {0} 선체 수리",
  "Report final victory {0} db": "최종 승리 보고 {0} DB",
  "Report the victory {0} db": "승리 보고 {0} DB",
  "Report to court {0} db": "법원 {0} DB에 신고하세요.",
  "Report victory {0} db": "승리 보고 {0} DB",
  "reported {0}": "{0}을 신고했습니다.",
  "reported animals to naturalist": "동물을 박물학자에게 보고했다",
  "reported completed fetch cargo": "화물 반입이 완료되었다고 보고됨",
  "Reported every known wonder to the patron of {0}.": "{0}의 후원자에게 알려진 모든 불가사의를 보고했습니다.",
  "reported pirate": "신고된 해적",
  "Reports from {0}: {1}": "{0}의 보고서: {1}",
  "Republic of Florence": "피렌체 공화국",
