  "Resident foreign settlements": "거주 외국인 정착지",
  "Responsum testimony": "응답 증언",
  "Resupply +{0} db. Harbor under attack.": "재보급 보상 +{0} DB. 항구 공격받는 중.",
  "return for {0} doubloons. {1}": "{0} 금화로 반환하세요. {1}",
  "Return only when the port is secured.": "포트가 확보된 경우에만 반환하십시오.",
  "Return the silver cup": "은잔을 돌려주세요",
  "Return to {0}": "{0}으로 돌아가기",
  "Return to {0}; {1}'s treasury owes you {2} doubloons.": "{0}으로 돌아가세요. {1}의 금고에서 {2}금화를 빚지고 있습니다.",
  "Return to Jeddah {0} db": "제다 {0} DB로 돌아가기",
  "Return to ship": "배로 돌아가기",
  "RETURN TO START MENU": "시작 메뉴로 돌아가기",
  "Return to the cook at {0} for the feast at sunset.": "해질녘 잔치를 위해 {0}에 있는 요리사에게 돌아가세요.",
  "Return to the quay": "부두로 돌아간다",
  "RETURN TO THE SHIPPING OFFICE AT NINGBO": "닝보 배송 사무소로 돌아가기",
  "RETURN WITH THE FULL SUM": "전액을 마련해 돌아온다",
  "returned rescued traveler to inaccessible home port": "구조된 여행자를 접근 불가능한 본국 항구로 돌려보냈습니다.",
  "Reunite with family in {0}": "{0}에서 가족과 재회하세요",
  "Reunited rescued traveler with family in {0}": "구조된 여행자가 {0}에서 가족과 재회했습니다.",
  "Reveal the hidden forgeries": "숨겨진 위조 문서를 밝힌다",
  "Review the prize": "상품 검토",
  "Reward {0}": "보상 {0}",
  "rgba(234, 216, 178, 0.9)": "RGBA(234, 216, 178, 0.9)",
  "rgba(249, 194, 43, 0.07)": "RGBA(249, 194, 43, 0.07)",
