  "rgba(80, 61, 42, 0.94)": "RGBA(80, 61, 42, 0.94)",
  "Rhinoceros": "코뿔소",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry": "로즈는 쓰러졌지만 기사단의 맹세는 그렇지 않았습니다. 성하께서는 당신이 가지고 다니기를 원하셨습니다",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat": "로즈는 쓰러졌지만 기사단의 서약은 무너지지 않았습니다. 성하께서는 스페인의 국왕이자 황제인 카를로스에게 몰타를 새로운 자리로 허락해 달라는 청원서를 가지고 오라고 하셨습니다.",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat{0}": "로즈는 쓰러졌지만 기사단의 맹세는 그렇지 않았습니다. 성하께서는 스페인의 국왕이자 황제인 카를로스에게 몰타에 새로운 자리를 부여해 달라는 청원서를 전달하라고 하셨습니다{0}",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat{0}.": "로즈는 쓰러졌지만 기사단의 맹세는 그렇지 않았습니다. 성하께서는 스페인 왕이자 황제인 카를로스에게 몰타에 새로운 자리를 부여해 달라는 청원서를 전달하라고 하셨습니다{0}.",
  "Rhodes is lost behind us. At Birgu we shall raise the eight-pointed cross again, and": "로즈는 우리 뒤에서 길을 잃었습니다. 비르구에서 우리는 다시 팔각 십자가를 올릴 것이며,",
  "Rhodes is lost behind us. At Birgu we shall raise the eight-pointed cross again, and make a fortress of our exile.": "로즈는 우리 뒤에서 길을 잃었습니다. 비르구에서 우리는 다시 팔각 십자가를 세우고 우리 유배의 요새를 만들 것이다.",
  "Rhodes still stands before the Ottoman sea, but courage cannot feed its defenders.": "로즈는 여전히 오스만 바다 앞에 서 있지만, 용기를 내어 수비수들에게 먹이를 줄 수는 없습니다.",
  "Rhodes still stands before the Ottoman sea, but courage cannot feed its defenders. Carry {0} and a Papal nuncio to {1}.": "로즈는 여전히 오스만 바다 앞에 서 있지만, 용기를 내어 수비수들에게 먹이를 줄 수는 없습니다. {0}과 교황 대사를 {1}로 데려가세요.",
  "Ribeira Grande": "리베이라그란데",
  "RIGHT": "오른쪽",
  "Ring; your presence will show that the Order yet lives.": "링; 당신의 존재는 기사단이 아직 살아 있다는 것을 보여줄 것입니다.",
  "ritual envoy": "의례사절",
