  "Sao Paulo de Luanda has become Portugal's fortified Angolan port. Its Atlantic wealth comes from inland war and the slave trade.": "상파울루 데 루안다는 포르투갈의 요새화된 앙골라 항구가 되었습니다. 대서양의 부는 내전과 노예 무역에서 비롯됩니다.",
