  "Sharifate of Mecca": "메카의 샤리파테",
  "Shasta rises by itself above the forests, a broad volcanic cone with a smaller shoulder beside it. Snowfields catch the light long after the lower country has gone dark.": "샤스타는 옆에 더 작은 어깨가 있는 넓은 원뿔형 화산 원뿔인 숲 위로 저절로 솟아 있습니다. 눈밭은 낮은 나라가 어두워진 후에도 오랫동안 빛을 받습니다.",
  "Shawmut has good water but little ready shelter for a fleet of families. Bring": "Shawmut에는 좋은 물이 있지만 많은 가족을 위한 준비된 피난처가 거의 없습니다. 가져오다",
